// Data of the panels: design tokens from srl.config and the viewport of the page. In the tab the
// width comes from the page (overlay plugin) through the channel, on the page from window.
import { computed, ref, type ComputedRef, type Ref } from 'vue'
// @ts-expect-error Nuxt alias, generated by the srl module
import { useSrlDesignConfig } from '#srl/design-config'
import { DEFAULT_BREAKPOINTS, viewportFor, type SrlBreakpoints } from '../utils/viewport'
import { openChannel } from './shared'

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type DesignConfig = Record<string, any>

const designConfig = useSrlDesignConfig() as Ref<DesignConfig>
const width = ref(0)
/** false in the tab until the page answered (page not open or overlay disabled). */
export const pageConnected = ref(false)

/** Starts tracking the width: `page` = own window, `tab` = the page through the channel. */
export function trackViewport(source: 'page' | 'tab') {
  if (source === 'page') {
    const channel = openChannel((message) => {
      if (message.type === 'request-viewport') channel.post({ type: 'viewport', width: width.value })
    })
    const update = () => {
      width.value = window.innerWidth
      channel.post({ type: 'viewport', width: width.value })
    }
    window.addEventListener('resize', update, { passive: true })
    update()
    pageConnected.value = true
  } else {
    const channel = openChannel((message) => {
      if (message.type === 'viewport') {
        width.value = message.width
        pageConnected.value = true
      }
    })
    channel.post({ type: 'request-viewport' })
  }
}

const viewPort = computed(() => {
  const breakPoints: SrlBreakpoints = designConfig.value.grid?.breakpoints ?? DEFAULT_BREAKPOINTS
  return { breakPoints, innerWidth: width.value, viewPort: width.value ? viewportFor(width.value, breakPoints) : null }
})

/** srl.config design tokens (SRL 1 `useSrlConfig()` of the dev tools). */
export function useSrlConfig(): Ref<DesignConfig> {
  return designConfig
}

/** Viewport of the page (SRL 1 `useViewPort()`). */
export function useViewPort(): ComputedRef<{ breakPoints: SrlBreakpoints; innerWidth: number; viewPort: string | null }> {
  return viewPort
}
